"""Hosted model comparison (motion capability): the same Leo-and-Ben scene generated by each candidate video model.

The first frame is composed from the APPROVED artwork (each character's approved neutral pose on the approved living-room
plate), so every model starts from exactly the studio's characters. Clips are saved as videos of a dedicated
"Model comparison" episode, so they appear in the Video Library for review next to each other.
"""
from __future__ import annotations

import json
import os
from pathlib import Path

from PIL import Image

from .config import REPO_ROOT

TITLE = "Model comparison: Leo & Ben"
PROMPT = ("2D flat cartoon animation in a cozy living room, static camera. Two cartoon stickman characters with big round "
          "heads, large round white eyes, thin solid black stick arms and legs, black mitten hands and bold clean black "
          "outlines. The character on the left, in a teal sweater vest, talks excitedly and gestures with both hands. The "
          "character on the right, in a purple hoodie and backwards cap, turns his head towards him, scratches his head "
          "with one hand and reacts with surprise. Keep the exact flat cartoon style, flat colours and proportions.")
# Round 2: controlled character actions. One identical prompt for every model, explicit timed beats, full bodies,
# and the SAME clip length on every model (about 5.04 s, see SCENARIO_PARAMS), so movement can be judged fairly.
ACTION_PROMPT = (
    "2D flat cartoon animation, static camera, full bodies visible from head to shoes the whole time. Two cartoon "
    "stickman characters stand in a cozy living room: LEFT is the character in the teal sweater vest, RIGHT is the "
    "character in the purple hoodie and backwards cap. Big, clear, exaggerated cartoon acting in this order: "
    "First second: the LEFT character raises both arms high and waves his hands while talking excitedly. "
    "Seconds 1 to 3: the RIGHT character turns his whole body towards him, lifts one arm and scratches the top of his "
    "head, looking guilty. Seconds 3 to 5: the LEFT character takes one step towards him and points straight at him; "
    "the RIGHT character jumps back and throws both arms up in surprise. Keep both characters exactly as drawn: big "
    "round heads, large round white eyes, thin solid black stick arms and legs, black mitten hands, bold black "
    "outlines, flat colours, same clothes, same proportions.")
SCENARIOS = {
    "talk": {"label": "Round 1: talk and react", "prompt": None},
    "actions": {"label": "Round 2: controlled actions", "prompt": ACTION_PROMPT},
}
# per scenario and model: generation settings that give the same clip length everywhere (round 1 keeps the defaults)
SCENARIO_PARAMS = {
    "actions": {"wan-2.2-a14b": {"num_frames": 81, "frames_per_second": 16},     # 5.06 s
                "wan-2.2-5b": {"num_frames": 121, "frames_per_second": 24},      # 5.04 s
                "ltx-2-19b": {"num_frames": 121, "fps": 24}},                    # 5.04 s
}

NEGATIVE = ("realistic, photo, 3d render, human skin texture, real hands, fingers, extra limbs, thick limbs, deformed, "
            "blurry, morphing face, different character, text, watermark")


def compose_first_frame(db, ctx_folder: Path) -> Path:
    """Leo and Ben (approved neutral poses) standing on the approved plate, 720x1280."""
    from .models import Character
    from . import acting
    st = json.loads((acting.ANIM / "sets" / "living-room-empty-03.json").read_text())
    plate = Image.open(REPO_ROOT / st["plate"]).convert("RGB")
    x0, x1 = 175, 935
    w = x1 - x0
    h = int(w * 16 / 9)
    y1 = st["height"]
    frame = plate.crop((x0, y1 - h, x1, y1))
    k = 720 / w
    frame = frame.resize((720, 1280), Image.LANCZOS)   # exactly 9:16 for the video models
    for key, fx in (("leo", 395), ("ben", 680)):
        c = db.query(Character).filter_by(key=key).one()
        reg = acting._registry(c)
        pid = c.expressions.get("neutral") or next(iter(c.expressions.values()))
        pose = reg["poses"][pid]
        img = Image.open(acting._pose_file(reg, pid)).convert("RGBA")
        fig_h = 530 * k
        s = fig_h / pose["figureHeight"]
        img = img.resize((max(1, int(img.width * s)), max(1, int(img.height * s))), Image.LANCZOS)
        feet = (pose["feet"]["x"] * s, pose["feet"]["y"] * s)
        frame.paste(img, (int((fx - x0) * k - feet[0]), int((st["floor_y"] - (y1 - h)) * k - feet[1])), img)
    out = ctx_folder / "first-frame.png"
    frame.save(out)
    return out


def comparison_episode(db):
    from .models import Episode
    ep = db.query(Episode).filter_by(title=TITLE).first()
    if not ep:
        ep = Episode(title=TITLE, stage="script_pending", format="short")
        db.add(ep)
        db.commit()
    return ep


def public_url(rel: str) -> str:
    base = os.environ.get("PUBLIC_URL", "").rstrip("/")
    return base + rel if rel.startswith("/") else rel


# ---------------------------------------------------------------- jobs
from .tasks import Ctx, store_asset, task  # noqa: E402


def plan(db, models: list[str], attempts: int, scenario: str = "talk") -> dict:
    from . import fal
    rows = [{"model": m, "label": fal.MODELS[m]["label"], "attempt": a + 1,
             "estimated_usd": fal.estimate(m, SCENARIO_PARAMS.get(scenario, {}).get(m, {})),
             "price": fal.MODELS[m]["price"], "licence": fal.MODELS[m]["licence"]} for m in models for a in range(attempts)]
    led = fal.spent(db)
    total = round(sum(r["estimated_usd"] for r in rows), 2)
    return {"requests": rows, "estimated_total_usd": total, "spent_usd": round(led["total"], 2), "budget_usd": fal.budget(db),
            "fits_budget": led["total"] + total <= fal.budget(db) + 1e-9}


@task
def motion_compare(ctx: Ctx) -> dict:
    """Compose the approved first frame, then queue one generation per model and attempt."""
    from .queue import enqueue
    from .storage import storage
    from .tasks import prepare_characters
    db, job = ctx.db, ctx.job
    prepare_characters(ctx)
    ep = comparison_episode(db)
    frame = compose_first_frame(db, ctx.folder("comparison", job.id))
    a = store_asset(db, ep_id=ep.id, src=frame, key=f"episodes/{ep.id}/comparison/first-frame-job{job.id}.png", kind="scene-reference",
                    label="Comparison first frame (approved Leo and Ben artwork)", content_type="image/png", job_id=job.id)
    db.commit()
    queued = []
    for m in job.payload["models"]:
        for i in range(int(job.payload.get("attempts", 1))):
            sc = job.payload.get("scenario", "talk")
            j = enqueue(db, "motion_generate", episode_id=ep.id,
                        payload={"model": m, "attempt": i + 1, "frame_asset_id": a.id, "scenario": sc,
                                 "prompt": SCENARIOS[sc]["prompt"] or PROMPT, "negative": NEGATIVE,
                                 "params": SCENARIO_PARAMS.get(sc, {}).get(m, {})})
            queued.append(j.id)
    ctx.log(f"first frame composed; {len(queued)} generation job(s) queued")
    return {"episode_id": ep.id, "frame_asset_id": a.id, "jobs": queued, "frame_url": storage().url(a.storage_key)}


@task
def motion_generate(ctx: Ctx) -> dict:
    from . import fal
    from .models import Asset
    from .storage import storage
    db, job = ctx.db, ctx.job
    p = job.payload
    frame = db.get(Asset, p["frame_asset_id"])
    image_url = public_url(storage().url(frame.storage_key, 7200))
    params = {"negative_prompt": p.get("negative", ""), **(p.get("params") or {})}
    if p["model"] == "ltx-2-19b":
        params["generate_audio"] = False

    def progress(info):
        job.progress = info
        db.commit()

    out = ctx.folder("comparison", "clips") / f"{p['model']}-a{p['attempt']}-job{job.id}.mp4"
    meta = fal.generate(db, p["model"], image_url, p["prompt"], params, out, ctx.log, progress)
    sc = SCENARIOS.get(p.get("scenario", "talk"), SCENARIOS["talk"])["label"]
    label = f"{sc}: {fal.MODELS[p['model']]['label']}, attempt {p['attempt']} (${meta['actual_usd']:.2f}, {meta['seconds']} s)"
    v = store_asset(db, ep_id=job.episode_id, src=out, key=f"episodes/{job.episode_id}/comparison/{out.name}", kind="video",
                    label=label, content_type="video/mp4", job_id=job.id)
    db.commit()
    return {**meta, "asset_id": v.id, "label": label}
